#!/usr/bin/env python3
"""
ABRAXAS FINAL STABLE BUILD
Run from project root: python3 fix_stable.py

Fixes:
  - Splash page → /auth/signin flow
  - SolanaProvider at root (wallet connect works everywhere)
  - Auth routes (GitHub/X/Email via NextAuth)
  - No duplicate border keys in signin
  - Clean layout.tsx with both providers
  - Wallet adapter CSS overrides in globals.css
"""
import base64, os, sys

if not os.path.exists("app"):
    print("Run from project root"); sys.exit(1)

FILES = {
    "app/page.tsx": "",
    "app/layout.tsx": "",
    "app/globals.css": "",
    "app/auth/signin/page.tsx": "",
    "app/api/auth/[...nextauth]/route.ts": "Ly8gRklMRTogYXBwL2FwaS9hdXRoL1suLi5uZXh0YXV0aF0vcm91dGUudHMKaW1wb3J0IE5leHRBdXRoIGZyb20gIm5leHQtYXV0aCI7CmltcG9ydCB7IGF1dGhPcHRpb25zIH0gZnJvbSAiQC9saWIvYXV0aCI7CmNvbnN0IGhhbmRsZXIgPSBOZXh0QXV0aChhdXRoT3B0aW9ucyk7CmV4cG9ydCB7IGhhbmRsZXIgYXMgR0VULCBoYW5kbGVyIGFzIFBPU1QgfTsK",
    "lib/auth.ts": "",
    "components/SolanaProvider.tsx": "",
    "components/SessionProvider.tsx": "",
}

for path, enc in FILES.items():
    d = os.path.dirname(path)
    if d: os.makedirs(d, exist_ok=True)
    content = base64.b64decode(enc).decode("utf-8")
    open(path, "w", encoding="utf-8", newline="\n").write(content)
    print(f"WRITTEN  {path}  ({len(content.splitlines())} lines)")

# Remove old temp fix scripts from root
import glob
removed = []
for f in glob.glob("fix_*.py") + glob.glob("patch_*.sh"):
    if f != "fix_stable.py":
        os.remove(f); removed.append(f)
if removed:
    print("REMOVED " + ", ".join(removed))

print("""
Done. Run:
  npm run build
  git add -A
  git commit -m "fix: stable auth flow, splash page, SolanaProvider root wrap, clean layout"
  git push origin main
""")
